    private static Enchant e(String n,String m,String d,String u){return new Enchant(n,m,d,u);} private int category,page; private String status="Recommendations are guides; /enchants is authoritative.";
    public EnchantmentHubScreen(Screen parent){super(parent,"Enchantment Hub");}
    protected Tab tab(){return Tab.STUDIO;}protected String railPage(){return "Gameplay";}protected String workspaceTitle(){return "ENCHANTMENT HUB";}protected String workspaceSubtitle(){return "Suggested builds and plain-English explanations for every tool.";}
    private String category(){return DATA.keySet().stream().toList().get(category);}private List<Enchant> entries(){return DATA.get(category());}
    protected void initContent(){int gap=6,w=(contentW-gap*4)/5,i=0;for(String name:DATA.keySet()){final int c=i;button(contentX+i*(w+gap),contentY,w,20,name,b->{category=c;page=0;refreshHub();});i++;}int y=contentY+contentH-22;button(contentX,y,70,20,"Previous",b->{page=Math.max(0,page-1);});button(contentX+76,y,70,20,"Next",b->{if((page+1)*4<entries().size())page++;});button(contentX+152,y,100,20,"Open /enchants",b->minecraft.setScreen(new ChatScreen("/enchants",false)));primary(contentX+contentW-72,y,72,20,"Done",b->onClose());}
    private void refreshHub(){clearWidgets();initContent();}
    protected void renderContentBackground(GuiGraphics g,int mx,int my){Ui.rounded(g,contentX,contentY+29,contentW,contentH-57,0x70201A27);Ui.roundedOutline(g,contentX,contentY+29,contentW,contentH-57,Ui.LINE);}
    protected void renderContent(GuiGraphics g,int mx,int my,float pt){var list=entries();int from=page*4,to=Math.min(list.size(),from+4),y=contentY+39;g.drawString(font,category().toUpperCase()+" · "+list.size()+" ENCHANTMENTS",contentX+10,y,Ui.ACCENT_SOFT,false);y+=16;for(int i=from;i<to;i++){Enchant e=list.get(i);g.drawString(font,e.name+" · "+e.max,contentX+10,y,Ui.TEXT,false);g.drawString(font,Ui.ellipsize(font,e.description,contentW-20),contentX+10,y+12,Ui.MUTED,false);g.drawString(font,"Suggested: "+Ui.ellipsize(font,e.use,contentW-78),contentX+10,y+24,0xFFDB9BC8,false);y+=43;}g.drawString(font,Ui.ellipsize(font,status,contentW-270),contentX+260,contentY+contentH-17,Ui.MUTED,false);}
